class Solution:
    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:
        if not matrix or not matrix[0]:
            return 0

        m, n = len(matrix), len(matrix[0])
        # dp[i][j] = length of longest increasing path starting at (i, j)
        dp = [[0] * n for _ in range(m)]
        directions = ((1, 0), (-1, 0), (0, 1), (0, -1))

        def dfs(i: int, j: int) -> int:
            if dp[i][j]:
                return dp[i][j]
            best = 1
            val = matrix[i][j]
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and matrix[ni][nj] > val:
                    cand = 1 + dfs(ni, nj)
                    if cand > best:
                        best = cand
            dp[i][j] = best
            return best

        # Iterative DFS to avoid recursion depth issues on large matrices.
        def iterative_dfs(si: int, sj: int) -> int:
            if dp[si][sj]:
                return dp[si][sj]
            stack = [(si, sj, False)]
            while stack:
                i, j, processed = stack.pop()
                if processed:
                    best = 1
                    val = matrix[i][j]
                    for di, dj in directions:
                        ni, nj = i + di, j + dj
                        if 0 <= ni < m and 0 <= nj < n and matrix[ni][nj] > val:
                            cand = 1 + dp[ni][nj]
                            if cand > best:
                                best = cand
                    dp[i][j] = best
                else:
                    if dp[i][j]:
                        continue
                    stack.append((i, j, True))
                    val = matrix[i][j]
                    for di, dj in directions:
                        ni, nj = i + di, j + dj
                        if (0 <= ni < m and 0 <= nj < n
                                and matrix[ni][nj] > val and not dp[ni][nj]):
                            stack.append((ni, nj, False))
            return dp[si][sj]

        ans = 0
        for i in range(m):
            for j in range(n):
                cur = iterative_dfs(i, j)
                if cur > ans:
                    ans = cur
        return ans
