class Solution:
    def pathsWithMaxScore(self, board):
        MOD = 10**9 + 7
        n = len(board)
        NEG = -1
        dp_sum = [[NEG] * n for _ in range(n)]
        dp_cnt = [[0] * n for _ in range(n)]
        dp_sum[n-1][n-1] = 0
        dp_cnt[n-1][n-1] = 1

        for i in range(n-1, -1, -1):
            for j in range(n-1, -1, -1):
                if i == n-1 and j == n-1:
                    continue
                if board[i][j] == 'X':
                    continue
                best = NEG
                cnt = 0
                for di, dj in ((1, 0), (0, 1), (1, 1)):
                    ni, nj = i + di, j + dj
                    if ni < n and nj < n and dp_sum[ni][nj] != NEG:
                        s = dp_sum[ni][nj]
                        c = dp_cnt[ni][nj]
                        if s > best:
                            best = s
                            cnt = c
                        elif s == best:
                            cnt = (cnt + c) % MOD
                if best == NEG:
                    continue
                val = 0
                ch = board[i][j]
                if ch.isdigit():
                    val = int(ch)
                dp_sum[i][j] = best + val
                dp_cnt[i][j] = cnt % MOD

        if dp_sum[0][0] == NEG:
            return [0, 0]
        return [dp_sum[0][0], dp_cnt[0][0] % MOD]
