class Solution:
    def countRectangles(self, rectangles: List[List[int]], points: List[List[int]]) -> List[int]:
        from bisect import bisect_left

        # Group lengths by height (height <= 100)
        heights = [[] for _ in range(101)]
        for l, h in rectangles:
            heights[h].append(l)

        # Sort lengths for binary search
        for h in range(101):
            heights[h].sort()

        result = []
        for x, y in points:
            count = 0
            # Check all heights >= y
            for h in range(y, 101):
                if heights[h]:
                    # Count lengths >= x using binary search
                    idx = bisect_left(heights[h], x)
                    count += len(heights[h]) - idx
            result.append(count)

        return result
